  1	package com.pousada.marealto;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousada.marealto.api.*;
  7	import com.pousada.marealto.database.DatabaseManager;
  8	import com.pousada.marealto.repository.MessageRepository;
  9	import com.pousada.marealto.repository.ReservationRepository;
 10	import com.pousada.marealto.repository.RoomRepository;
 11	import com.pousada.marealto.service.MessageService;
 12	import com.pousada.marealto.service.ReportService;
 13	import com.pousada.marealto.service.ReservationService;
 14	import com.pousada.marealto.service.RoomService;
 15	import io.javalin.Javalin;
 16	import io.javalin.json.JavalinJackson;
 17	
 18	public class Main {
 19	    public static void main(String[] args) {
 20	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 21	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 22	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 23	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 24	
 25	        DatabaseManager dbManager = new DatabaseManager(dbUrl, dbUser, dbPassword);
 26	        dbManager.initializeSchema();
 27	
 28	        RoomRepository roomRepository = new RoomRepository(dbManager);
 29	        ReservationRepository reservationRepository = new ReservationRepository(dbManager);
 30	        MessageRepository messageRepository = new MessageRepository(dbManager);
 31	
 32	        RoomService roomService = new RoomService(roomRepository);
 33	        MessageService messageService = new MessageService(messageRepository);
 34	        ReservationService reservationService = new ReservationService(
 35	            reservationRepository, roomService, messageService
 36	        );
 37	        ReportService reportService = new ReportService(reservationRepository);
 38	
 39	        ObjectMapper objectMapper = new ObjectMapper();
 40	        objectMapper.registerModule(new JavaTimeModule());
 41	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 42	
 43	        RoomController roomController = new RoomController(roomService);
 44	        ReservationController reservationController = new ReservationController(
 45	            reservationService, messageService, objectMapper
 46	        );
 47	        MessageController messageController = new MessageController(messageService);
 48	        ReportController reportController = new ReportController(reportService);
 49	
 50	        Javalin app = Javalin.create(config -> {
 51	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 52	        }).start(port);
 53	
 54	        app.get("/rooms", roomController::getRooms);
 55	
 56	        app.post("/reservations", reservationController::createReservation);
 57	        app.get("/reservations/{id}", reservationController::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 59	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 60	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 62	        app.get("/reservations/{id}/document", reservationController::getDocument);
 63	
 64	        app.get("/messages", messageController::getMessages);
 65	
 66	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 67	        app.get("/reports/revenue", reportController::getRevenueReport);
 68	
 69	        System.out.println("Pousada Maré Alta API running on port " + port);
 70	    }
 71	}
 72	package com.pousada.marealto.api;
 73	
 74	import com.pousada.marealto.messaging.Message;
 75	import com.pousada.marealto.service.MessageService;
 76	import io.javalin.http.Context;
 77	
 78	import java.util.HashMap;
 79	import java.util.List;
 80	import java.util.Map;
 81	
 82	public class MessageController {
 83	    private final MessageService messageService;
 84	
 85	    public MessageController(MessageService messageService) {
 86	        this.messageService = messageService;
 87	    }
 88	
 89	    public void getMessages(Context ctx) {
 90	        List<Message> messages = messageService.getAllMessages();
 91	        List<Map<String, Object>> response = messages.stream()
 92	            .map(this::messageToMap)
 93	            .toList();
 94	        ctx.json(response);
 95	    }
 96	
 97	    private Map<String, Object> messageToMap(Message message) {
 98	        Map<String, Object> map = new HashMap<>();
 99	        map.put("id", message.getId());
100	        map.put("channel", message.getChannel().name());
101	        map.put("to", message.getTo());
102	        map.put("subject", message.getSubject());
103	        map.put("body", message.getBody());
104	        return map;
105	    }
106	}
