118	public class ReportController {
119	    private final ReportService reportService;
120	
121	    public ReportController(ReportService reportService) {
122	        this.reportService = reportService;
123	    }
124	
125	    public void getOccupancyReport(Context ctx) {
126	        try {
127	            String dateParam = ctx.queryParam("date");
128	            if (dateParam == null) {
129	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing required parameter: date");
130	                return;
131	            }
132	
133	            LocalDate date = LocalDate.parse(dateParam);
134	            String csv = reportService.generateOccupancyReport(date);
135	
136	            ctx.contentType("text/csv; charset=utf-8")
137	               .result(csv);
138	        } catch (DateTimeParseException e) {
139	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid date format");
140	        }
141	    }
142	
143	    public void getRevenueReport(Context ctx) {
144	        try {
145	            String monthParam = ctx.queryParam("month");
146	            if (monthParam == null) {
147	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing required parameter: month");
148	                return;
149	            }
150	
151	            YearMonth yearMonth = YearMonth.parse(monthParam);
152	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
153	
154	            ctx.contentType("text/csv; charset=utf-8")
155	               .result(csv);
156	        } catch (DateTimeParseException e) {
157	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid month format");
158	        }
159	    }
160	
161	    private void errorResponse(Context ctx, int status, String code, String message) {
162	        Map<String, String> error = new HashMap<>();
163	        error.put("error", code);
164	        error.put("message", message);
165	        ctx.status(status).json(error);
166	    }
167	}
168	package com.pousada.marealto.api;
169	
170	import com.fasterxml.jackson.databind.ObjectMapper;
171	import com.pousada.marealto.domain.RatePlan;
172	import com.pousada.marealto.domain.Reservation;
173	import com.pousada.marealto.service.MessageService;
174	import com.pousada.marealto.service.ReservationService;
175	import io.javalin.http.Context;
176	
177	import java.time.LocalDate;
178	import java.time.format.DateTimeParseException;
179	import java.util.HashMap;
180	import java.util.Map;
181	
182	public class ReservationController {
183	    private final ReservationService reservationService;
184	    private final MessageService messageService;
185	    private final ObjectMapper objectMapper;
186	
187	    public ReservationController(ReservationService reservationService,
188	                                MessageService messageService,
189	                                ObjectMapper objectMapper) {
190	        this.reservationService = reservationService;
191	        this.messageService = messageService;
192	        this.objectMapper = objectMapper;
193	    }
194	
195	    public void createReservation(Context ctx) {
196	        try {
197	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
198	
199	            Reservation reservation = new Reservation();
200	            reservation.setRoomNumber(getRequiredString(body, "roomNumber"));
201	            reservation.setGuestName(getRequiredString(body, "guestName"));
202	            reservation.setGuestEmail(getRequiredString(body, "guestEmail"));
203	            reservation.setGuestCpf(getRequiredString(body, "guestCpf"));
204	            reservation.setCheckIn(parseDate(getRequiredString(body, "checkIn")));
205	            reservation.setCheckOut(parseDate(getRequiredString(body, "checkOut")));
206	            reservation.setGuests(getRequiredInt(body, "guests"));
207	            reservation.setRatePlan(RatePlan.valueOf(getRequiredString(body, "ratePlan")));
208	
209	            if (body.containsKey("companyCode") && body.get("companyCode") != null) {
210	                reservation.setCompanyCode((String) body.get("companyCode"));
211	            }
212	
213	            Reservation created = reservationService.createReservation(reservation);
214	            ctx.status(201).json(reservationToMap(created));
215	        } catch (IllegalArgumentException e) {
216	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
217	        } catch (ReservationService.InvalidRequestException e) {
218	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
219	        } catch (ReservationService.RoomUnavailableException e) {
220	            errorResponse(ctx, 409, "ROOM_UNAVAILABLE", e.getMessage());
221	        } catch (ReservationService.CapacityExceededException e) {
222	            errorResponse(ctx, 422, "CAPACITY_EXCEEDED", e.getMessage());
223	        } catch (Exception e) {
224	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid request data");
225	        }
226	    }
227	
228	    public void getReservation(Context ctx) {
229	        try {
230	            Long id = Long.parseLong(ctx.pathParam("id"));
231	            Reservation reservation = reservationService.getReservation(id);
232	            ctx.json(reservationToMap(reservation));
233	        } catch (ReservationService.ReservationNotFoundException e) {
234	            errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage());
235	        } catch (NumberFormatException e) {
236	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid reservation ID");
237	        }
238	    }
239	
240	    public void confirmReservation(Context ctx) {
241	        try {
242	            Long id = Long.parseLong(ctx.pathParam("id"));
243	            Reservation reservation = reservationService.confirmReservation(id);
244	            ctx.json(reservationToMap(reservation));
245	        } catch (ReservationService.ReservationNotFoundException e) {
246	            errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage());
247	        } catch (ReservationService.OperationNotAllowedException e) {
248	            errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
249	        } catch (NumberFormatException e) {
250	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid reservation ID");
251	        }
252	    }
253	
254	    public void cancelReservation(Context ctx) {
255	        try {
256	            Long id = Long.parseLong(ctx.pathParam("id"));
257	            Reservation reservation = reservationService.cancelReservation(id);
258	            ctx.json(reservationToMap(reservation));
259	        } catch (ReservationService.ReservationNotFoundException e) {
260	            errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage());
261	        } catch (ReservationService.OperationNotAllowedException e) {
262	            errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
263	        } catch (NumberFormatException e) {
264	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid reservation ID");
265	        }
266	    }
267	
268	    public void checkIn(Context ctx) {
269	        try {
270	            Long id = Long.parseLong(ctx.pathParam("id"));
271	            Reservation reservation = reservationService.checkIn(id);
272	            ctx.json(reservationToMap(reservation));
273	        } catch (ReservationService.ReservationNotFoundException e) {
274	            errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage());
275	        } catch (ReservationService.OperationNotAllowedException e) {
276	            errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
277	        } catch (NumberFormatException e) {
278	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid reservation ID");
279	        }
280	    }
281	
282	    public void checkOut(Context ctx) {
283	        try {
284	            Long id = Long.parseLong(ctx.pathParam("id"));
285	            Reservation reservation = reservationService.checkOut(id);
286	            ctx.json(documentToMap(reservation));
287	        } catch (ReservationService.ReservationNotFoundException e) {
288	            errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage());
289	        } catch (ReservationService.OperationNotAllowedException e) {
290	            errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
291	        } catch (NumberFormatException e) {
292	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid reservation ID");
293	        }
294	    }
295	
296	    public void getDocument(Context ctx) {
297	        try {
298	            Long id = Long.parseLong(ctx.pathParam("id"));
299	            Reservation reservation = reservationService.getReservation(id);
300	
301	            if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
302	                errorResponse(ctx, 400, "INVALID_REQUEST", "Document only available for paid reservations");
303	                return;
304	            }
305	
306	            ctx.json(documentToMap(reservation));
307	        } catch (ReservationService.ReservationNotFoundException e) {
308	            errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage());
309	        } catch (NumberFormatException e) {
310	            errorResponse(ctx, 400, "INVALID_REQUEST", "Invalid reservation ID");
311	        }
312	    }
313	
314	    private Map<String, Object> reservationToMap(Reservation r) {
315	        Map<String, Object> map = new HashMap<>();
316	        map.put("id", r.getId());
317	        map.put("roomNumber", r.getRoomNumber());
318	        map.put("guestName", r.getGuestName());
319	        map.put("guestEmail", r.getGuestEmail());
320	        map.put("guestCpf", r.getGuestCpf());
321	        map.put("checkIn", r.getCheckIn().toString());
322	        map.put("checkOut", r.getCheckOut().toString());
323	        map.put("guests", r.getGuests());
324	        map.put("ratePlan", r.getRatePlan().name());
325	        map.put("nights", r.getNights());
326	        map.put("subtotal", r.getSubtotal());
327	        map.put("discount", r.getDiscount());
328	        map.put("total", r.getTotal());
329	        map.put("status", r.getStatus().name());
330	        map.put("amountPaid", r.getAmountPaid());
331	        map.put("refund", r.getRefund());
332	        return map;
333	    }
334	
335	    private Map<String, Object> documentToMap(Reservation r) {
336	        Map<String, Object> map = new HashMap<>();
337	        map.put("title", "Comprovante de reserva");
338	        map.put("reservationId", r.getId());
339	        map.put("guestName", r.getGuestName());
340	        map.put("guestCpf", r.getGuestCpf());
341	        map.put("roomNumber", r.getRoomNumber());
342	        map.put("roomType", getRoomType(r.getRoomNumber()));
343	        map.put("checkIn", r.getCheckIn().toString());
344	        map.put("checkOut", r.getCheckOut().toString());
345	        map.put("nights", r.getNights());
346	        map.put("subtotal", r.getSubtotal());
347	        map.put("discount", r.getDiscount());
348	        map.put("total", r.getTotal());
349	        return map;
350	    }
351	
352	    private String getRoomType(String roomNumber) {
353	        return switch (roomNumber) {
354	            case "101", "102" -> "STANDARD";
355	            case "201", "202" -> "DELUXE";
356	            case "301" -> "SUITE";
357	            default -> "UNKNOWN";
358	        };
359	    }
360	
361	    private String getRequiredString(Map<String, Object> map, String key) {
362	        Object value = map.get(key);
363	        if (value == null) {
364	            throw new IllegalArgumentException("Missing required field: " + key);
365	        }
366	        return value.toString();
367	    }
368	
369	    private int getRequiredInt(Map<String, Object> map, String key) {
370	        Object value = map.get(key);
371	        if (value == null) {
372	            throw new IllegalArgumentException("Missing required field: " + key);
373	        }
374	        if (value instanceof Number) {
375	            return ((Number) value).intValue();
376	        }
377	        return Integer.parseInt(value.toString());
378	    }
379	
380	    private LocalDate parseDate(String dateStr) {
381	        try {
382	            return LocalDate.parse(dateStr);
383	        } catch (DateTimeParseException e) {
384	            throw new IllegalArgumentException("Invalid date format: " + dateStr);
385	        }
386	    }
387	
388	    private void errorResponse(Context ctx, int status, String code, String message) {
389	        Map<String, String> error = new HashMap<>();
390	        error.put("error", code);
391	        error.put("message", message);
392	        ctx.status(status).json(error);
393	    }
394	}
