369	    private int getRequiredInt(Map<String, Object> map, String key) {
370	        Object value = map.get(key);
371	        if (value == null) {
372	            throw new IllegalArgumentException("Missing required field: " + key);
373	        }
374	        if (value instanceof Number) {
375	            return ((Number) value).intValue();
376	        }
377	        return Integer.parseInt(value.toString());
