 22	    public void sendConfirmationEmail(Reservation reservation) {
 23	        String document = generateDocument(reservation);
 24	
 25	        String body = String.format("""
 26	            Olá, %s!
 27	
 28	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
 29	
 30	            %s
 31	
 32	            A entrada é a partir das 14h, e a saída, até as 12h.
 33	            Até breve!
 34	            """, reservation.getGuestName(), document);
 35	
 36	        Message message = new Message(
 37	            MessageChannel.EMAIL,
 38	            reservation.getGuestEmail(),
 39	            "Reserva confirmada - Pousada Maré Alta",
 40	            body
 41	        );
 42	
 43	        messageRepository.save(message);
 44	    }
