 46	    public String generateDocument(Reservation reservation) {
 47	        NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(PT_BR);
 48	
 49	        StringBuilder doc = new StringBuilder();
 50	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
 51	        doc.append("Hóspede: ").append(reservation.getGuestName())
 52	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
 53	
 54	        String roomType = getRoomType(reservation.getRoomNumber());
 55	        doc.append("Quarto: ").append(reservation.getRoomNumber())
 56	           .append(" (").append(roomType).append(")\n");
 57	
 58	        doc.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
 59	           .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
 60	           .append(" | ").append(reservation.getNights())
 61	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 62	
 63	        doc.append("Diárias: ").append(currencyFormat.format(reservation.getSubtotal())).append("\n");
 64	
 65	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
 66	            doc.append("Desconto: ").append(currencyFormat.format(reservation.getDiscount())).append("\n");
 67	        }
 68	
 69	        doc.append("Total: ").append(currencyFormat.format(reservation.getTotal()));
 70	
 71	        return doc.toString();
 72	    }
