 74	    private String formatCpf(String cpf) {
 75	        if (cpf == null || cpf.length() != 11) {
 76	            return cpf;
 77	        }
 78	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
 79	               cpf.substring(6, 9) + "-" + cpf.substring(9);
 80	    }
