106	public class ReportService {
107	    private final ReservationRepository reservationRepository;
108	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
109	    private static final int TOTAL_ROOMS = 5;
110	
111	    public ReportService(ReservationRepository reservationRepository) {
112	        this.reservationRepository = reservationRepository;
113	    }
114	
115	    public String generateOccupancyReport(LocalDate date) {
116	        List<Reservation> reservations = reservationRepository.findByDate(date);
117	
118	        StringBuilder csv = new StringBuilder();
119	        csv.append("room,type,reservation,check_in,check_out\n");
120	
121	        for (Reservation reservation : reservations) {
122	            csv.append(reservation.getRoomNumber()).append(",");
123	            csv.append(getRoomType(reservation.getRoomNumber())).append(",");
124	            csv.append(reservation.getId()).append(",");
125	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
126	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
127	        }
128	
129	        csv.append("total,").append(reservations.size()).append("/").append(TOTAL_ROOMS);
130	
131	        return csv.toString();
132	    }
133	
134	    public String generateRevenueReport(int year, int month) {
135	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
136	
137	        StringBuilder csv = new StringBuilder();
138	        csv.append("reservation,room,check_in,check_out,status,amount\n");
139	
140	        BigDecimal total = BigDecimal.ZERO;
141	
142	        for (Reservation reservation : reservations) {
143	            BigDecimal revenue = calculateRevenue(reservation);
144	
145	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
146	                csv.append(reservation.getId()).append(",");
147	                csv.append(reservation.getRoomNumber()).append(",");
148	                csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
149	                csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
150	                csv.append(reservation.getStatus().name()).append(",");
151	                csv.append(formatCsvDecimal(revenue)).append("\n");
152	
153	                total = total.add(revenue);
154	            }
155	        }
156	
157	        csv.append("total,").append(formatCsvDecimal(total));
158	
159	        return csv.toString();
160	    }
161	
162	    private BigDecimal calculateRevenue(Reservation reservation) {
163	        BigDecimal revenue = reservation.getAmountPaid();
164	
165	        if (reservation.getRefund() != null) {
166	            revenue = revenue.subtract(reservation.getRefund());
167	        }
168	
169	        return revenue;
170	    }
171	
172	    private String formatCsvDecimal(BigDecimal value) {
173	        return value.setScale(2, java.math.RoundingMode.HALF_EVEN)
174	                   .toString()
175	                   .replace(',', '.');
176	    }
