178	    private String getRoomType(String roomNumber) {
179	        return switch (roomNumber) {
180	            case "101", "102" -> "STANDARD";
181	            case "201", "202" -> "DELUXE";
182	            case "301" -> "SUITE";
183	            default -> "UNKNOWN";
184	        };
185	    }
186	}
