191	import com.pousada.marealto.domain.ReservationStatus;
192	import com.pousada.marealto.rateplan.*;
193	import com.pousada.marealto.repository.ReservationRepository;
194	
195	import java.math.BigDecimal;
196	import java.time.LocalDate;
197	import java.util.Optional;
198	
199	public class ReservationService {
200	    private final ReservationRepository reservationRepository;
201	    private final RoomService roomService;
202	    private final MessageService messageService;
203	
204	    public ReservationService(ReservationRepository reservationRepository,
205	                            RoomService roomService,
206	                            MessageService messageService) {
207	        this.reservationRepository = reservationRepository;
208	        this.roomService = roomService;
209	        this.messageService = messageService;
210	    }
211	
212	    public Reservation createReservation(Reservation reservation) {
213	        reservation.calculateNights();
214	
215	        if (reservation.getNights() < 1) {
216	            throw new InvalidRequestException("Check-out must be after check-in");
217	        }
218	
219	        if (reservation.getGuests() < 1) {
220	            throw new InvalidRequestException("At least one guest is required");
221	        }
222	
223	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
224	
225	        if (reservation.getGuests() > room.getCapacity()) {
226	            throw new CapacityExceededException("Room capacity exceeded");
227	        }
228	
229	        RatePlanStrategy strategy = RatePlanFactory.getStrategy(reservation.getRatePlan());
230	
231	        try {
232	            strategy.validate(reservation.getCheckIn(), reservation.getCheckOut(),
233	                            reservation.getNights(), reservation.getCompanyCode());
234	        } catch (IllegalArgumentException e) {
235	            throw new InvalidRequestException(e.getMessage());
236	        }
237	
238	        if (reservationRepository.hasConflictingReservation(reservation.getRoomNumber(),
239	                reservation.getCheckIn(), reservation.getCheckOut(), null)) {
240	            throw new RoomUnavailableException("Room is not available for the selected dates");
241	        }
242	
243	        PriceCalculation price;
244	        if (strategy instanceof CorporateRatePlan corporate) {
245	            price = corporate.calculatePrice(room.getType(), reservation.getCheckIn(),
246	                                           reservation.getCheckOut(), reservation.getNights(),
247	                                           reservation.getCompanyCode());
248	        } else {
249	            price = strategy.calculatePrice(room.getType(), reservation.getCheckIn(),
250	                                          reservation.getCheckOut(), reservation.getNights());
251	        }
252	
253	        reservation.setSubtotal(price.subtotal());
254	        reservation.setDiscount(price.discount());
255	        reservation.setTotal(price.total());
256	
257	        return reservationRepository.save(reservation);
258	    }
259	
260	    public Reservation getReservation(Long id) {
261	        return reservationRepository.findById(id)
262	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
263	    }
264	
265	    public Reservation confirmReservation(Long id) {
266	        Reservation reservation = getReservation(id);
267	
268	        if (reservation.getStatus() != ReservationStatus.PENDING) {
269	            throw new OperationNotAllowedException("Can only confirm pending reservations");
270	        }
271	
272	        reservation.confirm();
273	        reservationRepository.update(reservation);
274	
275	        messageService.sendConfirmationEmail(reservation);
276	
277	        return reservation;
278	    }
279	
280	    public Reservation cancelReservation(Long id) {
281	        Reservation reservation = getReservation(id);
282	
283	        if (reservation.getStatus() != ReservationStatus.PENDING &&
284	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
285	            throw new OperationNotAllowedException("Can only cancel pending or confirmed reservations");
286	        }
287	
288	        RatePlanStrategy strategy = RatePlanFactory.getStrategy(reservation.getRatePlan());
289	        BigDecimal refund = strategy.calculateRefund(reservation.getAmountPaid());
290	
291	        reservation.cancel();
292	        reservation.setRefund(refund);
293	        reservationRepository.update(reservation);
294	
295	        return reservation;
296	    }
297	
298	    public Reservation checkIn(Long id) {
299	        Reservation reservation = getReservation(id);
300	
301	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
302	            throw new OperationNotAllowedException("Can only check-in confirmed reservations");
303	        }
304	
305	        reservation.checkIn();
306	        reservationRepository.update(reservation);
307	
308	        return reservation;
309	    }
310	
311	    public Reservation checkOut(Long id) {
312	        Reservation reservation = getReservation(id);
313	
314	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
315	            throw new OperationNotAllowedException("Can only check-out checked-in reservations");
316	        }
317	
318	        reservation.checkOut();
319	        reservationRepository.update(reservation);
320	
321	        return reservation;
322	    }
323	
324	    public static class InvalidRequestException extends RuntimeException {
325	        public InvalidRequestException(String message) {
326	            super(message);
327	        }
328	    }
329	
330	    public static class ReservationNotFoundException extends RuntimeException {
331	        public ReservationNotFoundException(String message) {
332	            super(message);
333	        }
334	    }
335	
336	    public static class RoomUnavailableException extends RuntimeException {
