554	import java.time.LocalDate;
555	import java.time.Month;
556	
557	public class SeasonCalculator {
558	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
559	
560	    public static boolean isHighSeason(LocalDate date) {
561	        Month month = date.getMonth();
562	        int day = date.getDayOfMonth();
563	
564	        if (month == Month.DECEMBER && day >= 15) {
565	            return true;
566	        }
567	
568	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
569	            return true;
570	        }
571	
572	        if (month == Month.JULY) {
573	            return true;
574	        }
575	
576	        return false;
577	    }
578	
579	    public static BigDecimal calculateNightlyPrice(BigDecimal basePrice, LocalDate date) {
580	        if (isHighSeason(date)) {
581	            return round(basePrice.multiply(HIGH_SEASON_MULTIPLIER));
582	        }
583	        return basePrice;
584	    }
585	
586	    public static BigDecimal round(BigDecimal value) {
587	        return value.setScale(2, RoundingMode.HALF_EVEN);
588	    }
589	}
