  1	package com.pousada.marealto.rateplan;
  2	
  3	import com.pousada.marealto.domain.RoomType;
  4	import org.junit.jupiter.api.Test;
  5	
  6	import java.math.BigDecimal;
  7	import java.time.LocalDate;
  8	
  9	import static org.junit.jupiter.api.Assertions.*;
 10	
 11	class RatePlanTest {
 12	
 13	    @Test
 14	    void testStandardRatePlanHighSeason() {
 15	        StandardRatePlan plan = new StandardRatePlan();
 16	        PriceCalculation price = plan.calculatePrice(
 17	            RoomType.STANDARD,
 18	            LocalDate.of(2027, 7, 10),
 19	            LocalDate.of(2027, 7, 12),
 20	            2
 21	        );
 22	
 23	        assertEquals(new BigDecimal("599.76"), price.subtotal());
 24	        assertEquals(BigDecimal.ZERO, price.discount());
 25	        assertEquals(new BigDecimal("599.76"), price.total());
 26	    }
 27	
 28	    @Test
 29	    void testCorporateTecnosulDeluxe() {
 30	        CorporateRatePlan plan = new CorporateRatePlan();
 31	        PriceCalculation price = plan.calculatePrice(
 32	            RoomType.DELUXE,
 33	            LocalDate.of(2027, 3, 10),
 34	            LocalDate.of(2027, 3, 12),
 35	            2,
 36	            "TECNOSUL"
 37	        );
 38	
 39	        assertEquals(new BigDecimal("779.80"), price.subtotal());
 40	        assertEquals(new BigDecimal("93.58"), price.discount());
 41	        assertEquals(new BigDecimal("686.22"), price.total());
 42	    }
 43	
 44	    @Test
 45	    void testWeekendPackageDeluxe() {
 46	        WeekendPackageRatePlan plan = new WeekendPackageRatePlan();
 47	
 48	        assertDoesNotThrow(() -> {
 49	            plan.validate(
 50	                LocalDate.of(2027, 3, 12),
 51	                LocalDate.of(2027, 3, 14),
 52	                2,
 53	                null
 54	            );
 55	        });
 56	
 57	        PriceCalculation price = plan.calculatePrice(
 58	            RoomType.DELUXE,
 59	            LocalDate.of(2027, 3, 12),
 60	            LocalDate.of(2027, 3, 14),
 61	            2
 62	        );
 63	
 64	        assertEquals(new BigDecimal("820.00"), price.subtotal());
 65	        assertEquals(BigDecimal.ZERO, price.discount());
 66	        assertEquals(new BigDecimal("820.00"), price.total());
 67	    }
 68	
 69	    @Test
 70	    void testWeekendPackageRefund() {
 71	        WeekendPackageRatePlan plan = new WeekendPackageRatePlan();
 72	        BigDecimal refund = plan.calculateRefund(new BigDecimal("820.00"));
 73	
 74	        assertEquals(new BigDecimal("410.00"), refund);
 75	    }
 76	
 77	    @Test
 78	    void testLongStayStandard() {
 79	        LongStayRatePlan plan = new LongStayRatePlan();
 80	
 81	        assertDoesNotThrow(() -> {
 82	            plan.validate(
 83	                LocalDate.of(2027, 3, 1),
 84	                LocalDate.of(2027, 3, 8),
 85	                7,
 86	                null
 87	            );
 88	        });
 89	
 90	        PriceCalculation price = plan.calculatePrice(
 91	            RoomType.STANDARD,
 92	            LocalDate.of(2027, 3, 1),
 93	            LocalDate.of(2027, 3, 8),
 94	            7
 95	        );
 96	
 97	        assertEquals(new BigDecimal("1749.30"), price.subtotal());
 98	        assertEquals(new BigDecimal("174.93"), price.discount());
 99	        assertEquals(new BigDecimal("1574.37"), price.total());
100	    }
101	
102	    @Test
103	    void testCorporateInvalidCompanyCode() {
104	        CorporateRatePlan plan = new CorporateRatePlan();
105	
106	        assertThrows(IllegalArgumentException.class, () -> {
107	            plan.validate(
108	                LocalDate.of(2027, 3, 10),
109	                LocalDate.of(2027, 3, 12),
110	                2,
111	                "INVALID"
112	            );
113	        });
114	    }
115	
116	    @Test
117	    void testWeekendPackageNotFriday() {
118	        WeekendPackageRatePlan plan = new WeekendPackageRatePlan();
119	
120	        assertThrows(IllegalArgumentException.class, () -> {
121	            plan.validate(
122	                LocalDate.of(2027, 3, 13),
123	                LocalDate.of(2027, 3, 15),
124	                2,
125	                null
126	            );
127	        });
128	    }
129	
130	    @Test
131	    void testLongStayTooShort() {
132	        LongStayRatePlan plan = new LongStayRatePlan();
133	
134	        assertThrows(IllegalArgumentException.class, () -> {
135	            plan.validate(
136	                LocalDate.of(2027, 3, 1),
137	                LocalDate.of(2027, 3, 7),
138	                6,
139	                null
140	            );
141	        });
142	    }
143	
144	    @Test
145	    void testHighSeasonDetection() {
146	        assertTrue(SeasonCalculator.isHighSeason(LocalDate.of(2027, 12, 15)));
147	        assertTrue(SeasonCalculator.isHighSeason(LocalDate.of(2027, 12, 31)));
148	        assertTrue(SeasonCalculator.isHighSeason(LocalDate.of(2027, 1, 1)));
149	        assertTrue(SeasonCalculator.isHighSeason(LocalDate.of(2027, 2, 28)));
150	        assertTrue(SeasonCalculator.isHighSeason(LocalDate.of(2027, 7, 1)));
151	        assertTrue(SeasonCalculator.isHighSeason(LocalDate.of(2027, 7, 31)));
152	
153	        assertFalse(SeasonCalculator.isHighSeason(LocalDate.of(2027, 12, 14)));
154	        assertFalse(SeasonCalculator.isHighSeason(LocalDate.of(2027, 3, 1)));
155	        assertFalse(SeasonCalculator.isHighSeason(LocalDate.of(2027, 6, 30)));
156	        assertFalse(SeasonCalculator.isHighSeason(LocalDate.of(2027, 8, 1)));
157	    }
158	}

